<?php require __DIR__.'/../includes/app.php';need('System Administrator','Business Manager','Rental Officer');$can=user()['role']!=='Business Manager';$pdo=db();
function saveimg($iid){if(!empty($_FILES['img']['tmp_name'])&&$_FILES['img']['error']===0&&getimagesize($_FILES['img']['tmp_name'])){$x=strtolower(pathinfo($_FILES['img']['name'],PATHINFO_EXTENSION));if(in_array($x,['jpg','jpeg','png','webp'])){$f='uploads/'.bin2hex(random_bytes(8)).'.'.$x;move_uploaded_file($_FILES['img']['tmp_name'],__DIR__.'/../'.$f);q('INSERT INTO inspection_images(inspection_id,image_path,description) VALUES(?,?,?)',[$iid,$f,$_POST['img_desc']??null]);}}}
if($can&&$_SERVER['REQUEST_METHOD']==='POST'){chk();$p=$_POST;
 try{$pdo->beginTransaction();
 if($p['act']==='handover'){$r=q("SELECT r.*,a.agreement_id FROM reservations r JOIN rental_agreements a USING(reservation_id) WHERE r.reservation_id=? AND r.status='confirmed' AND a.status='signed' FOR UPDATE",[$p['rid']])->fetch();if(!$r)throw new Exception('Reservation must be confirmed with a signed agreement.');
  $driverId=(int)($r['requested_driver_id']?:($p['driver_id']??0));
  if(!$driverId)throw new Exception('Assign a company driver before handing over this rental. Self-driving is not allowed.');
  if(!q("SELECT driver_id FROM drivers WHERE driver_id=? AND availability_status='available' FOR UPDATE",[$driverId])->fetchColumn())throw new Exception('The assigned company driver is no longer available.');
  $driverConflict=q("SELECT COUNT(*) FROM reservations WHERE requested_driver_id=? AND reservation_id<>? AND status IN('pending','confirmed') AND pickup_datetime<? AND return_datetime>?",[$driverId,$r['reservation_id'],$r['return_datetime'],$r['pickup_datetime']])->fetchColumn();
  if($driverConflict)throw new Exception('The assigned company driver has another rental during this period.');
  if(empty($r['requested_driver_id']))q('UPDATE reservations SET requested_driver_id=? WHERE reservation_id=? AND requested_driver_id IS NULL',[$driverId,$r['reservation_id']]);
  $dep=q("SELECT COALESCE(SUM(amount),0) FROM deposit_transactions WHERE reservation_id=? AND transaction_type='received' AND status='completed'",[$r['reservation_id']])->fetchColumn();
  q("INSERT INTO rentals(rental_number,reservation_id,agreement_id,customer_id,vehicle_id,assigned_driver_id,actual_pickup_datetime,expected_return_datetime,pickup_mileage,pickup_fuel_percent,base_amount,tax_amount,discount_amount,final_amount,status,pickup_notes,handled_by) VALUES(?,?,?,?,?,?,NOW(),?,?,?,?,?,?,?,'active',?,?)",[code('RNT'),$r['reservation_id'],$r['agreement_id'],$r['customer_id'],$r['vehicle_id'],$driverId,$r['return_datetime'],$p['mileage'],$p['fuel'],$r['estimated_amount'],0,$r['discount_amount'],max(0,$r['estimated_amount']-$r['discount_amount']),$p['notes'],user()['id']]);$rid=$pdo->lastInsertId();
  q("INSERT INTO vehicle_inspections(rental_id,vehicle_id,inspected_by,inspection_type,odometer_reading,fuel_level_percent,exterior_condition,interior_condition,cleanliness,damage_notes) VALUES(?,?,?,'pickup',?,?,?,?,?,?)",[$rid,$r['vehicle_id'],user()['id'],$p['mileage'],$p['fuel'],$p['ext'],$p['int'],$p['clean'],$p['damage']]);saveimg($pdo->lastInsertId());
  q("UPDATE vehicles SET status='rented',current_mileage=?,fuel_level_percent=? WHERE vehicle_id=?",[$p['mileage'],$p['fuel'],$r['vehicle_id']]);q("UPDATE rental_agreements SET status='active' WHERE agreement_id=?",[$r['agreement_id']]);q('UPDATE invoices SET rental_id=? WHERE reservation_id=?',[$rid,$r['reservation_id']]);q('UPDATE deposit_transactions SET rental_id=? WHERE reservation_id=?',[$rid,$r['reservation_id']]);
  q('INSERT INTO driver_assignments(driver_id,rental_id,assigned_by) VALUES(?,?,?)',[$driverId,$rid,user()['id']]);q("UPDATE drivers SET availability_status='assigned' WHERE driver_id=?",[$driverId]);
  notify_customer($r['customer_id'],'rental_started','Rental started','Your vehicle has been handed over. Have a safe trip.','rental',$rid);audit('handover','rental',$rid);flash('Vehicle handed over. Rental started.');}
 elseif($p['act']==='return'){$r=q("SELECT r.*,v.make,v.model,rs.daily_rate,rs.reservation_id FROM rentals r JOIN vehicles v USING(vehicle_id) JOIN reservations rs ON rs.reservation_id=r.reservation_id WHERE r.rental_id=? AND r.status IN('active','overdue') FOR UPDATE",[$p['rental_id']])->fetch();if(!$r)throw new Exception('Rental not active.');
  if($p['mileage']<$r['pickup_mileage'])throw new Exception('Return mileage cannot be lower than pickup mileage.');
  $late=0;if(time()>strtotime($r['expected_return_datetime']))$late=ceil((time()-strtotime($r['expected_return_datetime']))/86400)*$r['daily_rate'];
  $dmg=(float)$p['damage_fee'];$cl=(float)$p['cleaning_fee'];$oth=(float)$p['other_charges'];$ex=$late+$dmg+$cl+$oth;
  q("UPDATE rentals SET actual_return_datetime=NOW(),return_mileage=?,return_fuel_percent=?,late_return_fee=?,damage_fee=?,cleaning_fee=?,other_charges=?,final_amount=final_amount+?,status='returned',return_notes=? WHERE rental_id=?",[$p['mileage'],$p['fuel'],$late,$dmg,$cl,$oth,$ex,$p['notes'],$r['rental_id']]);
  q("INSERT INTO vehicle_inspections(rental_id,vehicle_id,inspected_by,inspection_type,odometer_reading,fuel_level_percent,exterior_condition,interior_condition,cleanliness,damage_notes) VALUES(?,?,?,'return',?,?,?,?,?,?)",[$r['rental_id'],$r['vehicle_id'],user()['id'],$p['mileage'],$p['fuel'],$p['ext'],$p['int'],$p['clean'],$p['damage']]);saveimg($pdo->lastInsertId());
  $inv=q('SELECT invoice_id FROM invoices WHERE rental_id=? ORDER BY invoice_id LIMIT 1',[$r['rental_id']])->fetchColumn();
  if($inv&&$ex>0){foreach([['late_return','Late return charge',$late],['damage','Damage fee',$dmg],['cleaning','Cleaning fee',$cl],['other','Other charges',$oth]] as [$t,$d,$v])if($v>0)q('INSERT INTO invoice_items(invoice_id,item_type,description,unit_price,line_total) VALUES(?,?,?,?,?)',[$inv,$t,$d,$v,$v]);
   q("UPDATE invoices SET subtotal=subtotal+?,total_amount=total_amount+?,status=IF(status='paid','partially_paid',status) WHERE invoice_id=?",[$ex,$ex,$inv]);}
  $bad=trim($p['damage'])!==''||!empty($p['maint']);q('UPDATE vehicles SET status=?,current_mileage=?,fuel_level_percent=? WHERE vehicle_id=?',[$bad?'maintenance':'available',$p['mileage'],$p['fuel'],$r['vehicle_id']]);
  if($bad)q("INSERT INTO maintenance_records(maintenance_number,vehicle_id,reported_by,maintenance_type,title,description,start_date,odometer_reading,status) VALUES(?,?,?,'repair','Post-return check',?,CURDATE(),?,'scheduled')",[code('MNT'),$r['vehicle_id'],user()['id'],$p['damage'],$p['mileage']]);
  q("UPDATE reservations SET status='completed' WHERE reservation_id=?",[$r['reservation_id']]);q("UPDATE rental_agreements SET status='completed' WHERE agreement_id=?",[$r['agreement_id']]);
  q('UPDATE drivers SET availability_status="available" WHERE driver_id=?',[$r['assigned_driver_id']]);q('UPDATE driver_assignments SET unassigned_at=NOW() WHERE rental_id=? AND unassigned_at IS NULL',[$r['rental_id']]);
  notify_customer($r['customer_id'],'rental_returned','Vehicle return recorded','Your vehicle return has been recorded.'.($ex>0?' Additional charges of '.money($ex).' have been added to your invoice.':''),'rental',$r['rental_id']);if($ex>0)notify_role('Accountant/Cashier','return_charges_added','Return charges need review','Additional charges were added to a returned rental invoice.','rental',$r['rental_id']);audit('return','rental',$r['rental_id']);flash('Return recorded. Additional charges ('.money($ex).') were added to the invoice.');}
 elseif($p['act']==='close'){q("UPDATE rentals SET status='closed' WHERE rental_id=? AND status IN('returned','inspected')",[$p['rental_id']]);flash('Rental closed.');}
 $pdo->commit();}catch(Exception $x){if($pdo->inTransaction())$pdo->rollBack();flash($x->getMessage(),'danger');}
 header('Location: rentals.php');exit;}
