function cond($n){$o='';foreach(['excellent','good','fair','poor'] as $c)$o.='<option'.($c==='good'?' selected':'').'>'.$c.'</option>';return '<select name="'.$n.'" class="form-select form-select-sm">'.$o.'</select>';}
function ins(){return '<div class="col-md-3"><label class="small">Exterior</label>'.cond('ext').'</div><div class="col-md-3"><label class="small">Interior</label>'.cond('int').'</div><div class="col-md-3"><label class="small">Cleanliness</label><select name="clean" class="form-select form-select-sm"><option>clean</option><option>acceptable</option><option>needs_cleaning</option></select></div><div class="col-md-3"><label class="small">Photo</label><input type="file" name="img" accept="image/*" class="form-control form-control-sm"></div><div class="col-12"><label class="small">Damage notes</label><input name="damage" class="form-control form-control-sm"></div>';}
$ready=q("SELECT r.*,c.first_name,c.last_name,v.make,v.model,v.registration_no,v.current_mileage,v.fuel_level_percent,d.first_name driver_first_name,d.last_name driver_last_name FROM reservations r JOIN rental_agreements a USING(reservation_id) JOIN customers c ON c.customer_id=r.customer_id JOIN vehicles v ON v.vehicle_id=r.vehicle_id LEFT JOIN drivers d ON d.driver_id=r.requested_driver_id WHERE r.status='confirmed' AND a.status='signed' AND NOT EXISTS(SELECT 1 FROM rentals x WHERE x.reservation_id=r.reservation_id)")->fetchAll();
$availableDrivers=q("SELECT driver_id,first_name,last_name FROM drivers WHERE availability_status='available' ORDER BY first_name,last_name")->fetchAll();
$act=q("SELECT r.*,c.first_name,c.last_name,v.make,v.model,v.registration_no FROM rentals r JOIN customers c USING(customer_id) JOIN vehicles v USING(vehicle_id) WHERE r.status IN('active','overdue') ORDER BY expected_return_datetime")->fetchAll();
$hist=q("SELECT r.*,c.first_name,c.last_name,v.registration_no FROM rentals r JOIN customers c USING(customer_id) JOIN vehicles v USING(vehicle_id) WHERE r.status IN('returned','inspected','closed') ORDER BY rental_id DESC LIMIT 30")->fetchAll();?>
